// QUEUE/frontend/src/components/StaffDashboard.jsx
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import axios from 'axios';

const StaffDashboard = ({ clinicId, staffId, staffName }) => {
    const [queue, setQueue] = useState([]);
    const [summary, setSummary] = useState(null);
    const [socket, setSocket] = useState(null);
    
    useEffect(() => {
        // Connect to WebSocket
        const newSocket = io('http://localhost:3001', {
            auth: { userId: staffId, role: 'staff', clinicId }
        });
        
        setSocket(newSocket);
        
        newSocket.on('queue:initial', (data) => {
            setQueue(data);
        });
        
        newSocket.on('queue:updated', (data) => {
            setQueue(data);
            fetchSummary();
        });
        
        fetchSummary();
        
        return () => newSocket.close();
    }, [clinicId]);
    
    const fetchSummary = async () => {
        const response = await axios.get(`http://localhost:3001/api/reports/summary/${clinicId}`);
        setSummary(response.data.queue_summary);
    };
    
    const updateStatus = (appointmentId, newStatus) => {
        socket.emit('status:update', {
            appointmentId,
            newStatus,
            staffId,
            clinicId
        });
    };
    
    return (
        <div style={{ padding: '20px' }}>
            <h1>Queue Management Dashboard</h1>
            <p>Welcome, {staffName}</p>
            
            {/* Summary Cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px', margin: '20px 0' }}>
                <div style={{ padding: '15px', background: '#fef3c7', borderRadius: '8px' }}>
                    <div>Waiting</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary?.total_waiting || 0}</div>
                </div>
                <div style={{ padding: '15px', background: '#d1fae5', borderRadius: '8px' }}>
                    <div>In Consultation</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary?.in_consultation_count || 0}</div>
                </div>
                <div style={{ padding: '15px', background: '#dbeafe', borderRadius: '8px' }}>
                    <div>Completed Today</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary?.completed_today || 0}</div>
                </div>
                <div style={{ padding: '15px', background: '#e9d5ff', borderRadius: '8px' }}>
                    <div>Avg Wait Time</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary?.average_wait_minutes || 0} min</div>
                </div>
            </div>
            
            {/* Queue Table */}
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                    <tr style={{ background: '#f3f4f6' }}>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Position</th>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Patient Name</th>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Wait Time</th>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Status</th>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    {queue.map((patient) => (
                        <tr key={patient.appointment_id} style={{ borderBottom: '1px solid #e5e7eb' }}>
                            <td style={{ padding: '10px' }}>{patient.queue_position}</td>
                            <td style={{ padding: '10px' }}>{patient.patient_name}</td>
                            <td style={{ padding: '10px' }}>{patient.waiting_minutes} min</td>
                            <td style={{ padding: '10px' }}>
                                <span style={{
                                    padding: '4px 8px',
                                    borderRadius: '20px',
                                    background: patient.patient_status === 'waiting' ? '#fef3c7' : '#d1fae5'
                                }}>
                                    {patient.patient_status}
                                </span>
                            </td>
                            <td style={{ padding: '10px' }}>
                                {patient.patient_status === 'waiting' && (
                                    <button onClick={() => updateStatus(patient.appointment_id, 'in_consultation')}>
                                        Start
                                    </button>
                                )}
                                {patient.patient_status === 'in_consultation' && (
                                    <button onClick={() => updateStatus(patient.appointment_id, 'complete')}>
                                        Complete
                                    </button>
                                )}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default StaffDashboard;
